-- public.aqueduct_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.aqueduct_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_rank text; p player; b bridge; s bridge_span; v_short text; v_c int[]; v_chain jsonb;
begin
  select * into p from player where world_id = p_world and uid = p_uid;
  if p_action = 'plan_bridge' then
    return 'Aqueducts are set out from the pool, pond, fountain or hollow they pour into.';
  end if;
  if p_action = 'plan_aqueduct' then
    if p_target->>'kind' is distinct from 'tile' then return 'Choose where it pours.'; end if;
    if jsonb_typeof(p_target->'head') is distinct from 'array' then return 'Choose the water it draws from.'; end if;
    if not in_reach(p.x, p.y, p_target, false, (select d.range from action_def d where d.id = 'plan_aqueduct')) then
      return 'You are too far away from that.';
    end if;
    return aqueduct_plan(p_world, p_uid, (p_target->'head'->>0)::int, (p_target->'head'->>1)::int,
                         (p_target->>'x')::int, (p_target->>'y')::int)->>'refused';
  end if;
  select * into b from bridge where world_id = p_world and id = (p_target->>'id')::bigint and kind = 'aqueduct';
  if not found then return 'It is gone.'; end if;
  if p_action in ('build_aqueduct', 'build_bridge') then
    select * into s from bridge_span sp where sp.world_id = p_world and sp.bridge = b.id
      and not span_done(sp.needed) order by sp.n limit 1;
    if not found then return 'Finished.'; end if;
    if tool_ql(p_world, p_uid, 'trowel') <= 0 then
      return 'Need a ' || lower((select coalesce(name, 'trowel') from item_def where id = 'trowel')) || '.';
    end if;
    if sqrt((s.x + 0.5 - p.x) ^ 2 + (s.y + 0.5 - p.y) ^ 2) > 4.5 then
      return 'Stand by the open span.';
    end if;
    select e.key into v_short from jsonb_each(s.needed) e
      where (e.value)::int > 0 and not exists (select 1 from jsonb_each(s.needed) e3
        where (e3.value)::int > 0 and build_to_hand(p_world, p_uid, e3.key, s.x, s.y, null) > 0) order by e.key limit 1;
    -- Piece by piece, as a bridge: refused only when nothing it wants is to hand.
    if v_short is not null then
      return 'Span needs ' || span_wants(s.needed) || '; none to hand.';
    end if;
    return null;
  end if;
  -- gates: pulled down from as near either end as a bridge is (`bridge_pull_reach`), and on a settlement only by its
  -- builders, as a bridge is (`last_refusal`, `pullDownRefusal`), named by the job's own label.
  if p_action = 'set_aqueduct_mote' then
    if bridge_left(p_world, b.id) > 0 then return 'Finish the aqueduct first.'; end if;
    v_short := aqueduct_fed_by(p_world, b.id);
    if v_short is not null then return 'Already fed: ' || v_short || '.'; end if;
    if sqrt((b.ax + 0.5 - p.x) ^ 2 + (b.ay + 0.5 - p.y) ^ 2) > bridge_pull_reach() then
      return 'Stand at its head.';
    end if;
  elsif sqrt((b.ax + 0.5 - p.x) ^ 2 + (b.ay + 0.5 - p.y) ^ 2) > bridge_pull_reach()
     and sqrt((b.bx + 0.5 - p.x) ^ 2 + (b."by" + 0.5 - p.y) ^ 2) > bridge_pull_reach() then
    return 'Stand at one end of it.';
  end if;
  select dd.name, rank_lacks(p_world, dd.founded_by, p_uid, 'shape') into v_short, v_rank
    from (values (1, b.ax, b.ay), (2, b.bx, b."by")) v(o, x, y)
    cross join lateral deed_covering(p_world, v.x, v.y) dd
   where not may_shape(p_world, p_uid, v.x, v.y)
   order by v.o, dd.founded_at limit 1;
  if v_short is not null then
    return coalesce(v_rank, 'Part of ' || v_short || ': only builders may '
        || lower((select a.label from action_def a where a.id = p_action)) || ' there.');
  end if;
  if p_action = 'set_aqueduct_mote' then
    if pack_count(p_world, p_uid, water_mote()) < water_motes_each() then return water_mote_need(); end if;
    v_c := mote_corner(p_world, b.ax, b.ay);
    v_chain := settle_water(p_world, v_c[1], v_c[2], b.ax, b.ay);
    if v_chain ? 'refused' or not exists (select 1 from jsonb_array_elements(v_chain->'streams') st
                                           where st ? 'via' and (st->>'via')::bigint = b.id) then
      return 'No water would run along it from its head at ' || metres(b.height) || ' m.';
    end if;
  end if;
  return null;
end $function$
